def groups(M,thr=0.8):
    n=M.shape[0]; lab=-np.ones(n,int); g=0
    A=np.zeros((n,n))
    for i in range(n):
        for j in range(n):
            ok=(M[i]>=0)&(M[j]>=0)
            A[i,j]=(M[i][ok]==M[j][ok]).mean() if ok.sum()>0 else 0
    for i in range(n):
        if lab[i]<0:
            lab[i]=g
            for j in range(i+1,n):
                if lab[j]<0 and A[i,j]>=thr: lab[j]=g
            g+=1
    return lab,A
for s in range(4):
